public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
        return resolveArguments(actualTypeArguments, targetType);
    }
    return null;
}

private static Class<?>[] resolveArguments(Type[] actualTypeArguments, Class<?> targetType) {
    Class<?>[] resolvedClasses = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        resolvedClasses[i] = resolveArgument(actualTypeArguments[i], targetType);
    }
    return resolvedClasses;
}

private static Class<?> resolveArgument(Type actualTypeArgument, Class<?> targetType) {
    if (actualTypeArgument instanceof Class) {
        return (Class<?>) actualTypeArgument;
    } else if (actualTypeArgument instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) actualTypeArgument, targetType);
    } else if (actualTypeArgument instanceof WildcardType) {
        return resolveWildcard((WildcardType) actualTypeArgument, targetType);
    } else {
        return null;
    }
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    for (Type bound : bounds) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        }
    }
    return null;
}

