public static long readRawVarint64(byte[] buffer, int offset, int length) {
    int position = offset;
    int end = offset + length;
    long result = 0L;
    int shift = 0;
    while (position < end) {
        byte b = buffer[position++];
        result |= (long) (b & 0x7F) << shift;
        shift += 7;
        if ((b & 0x80) != 0) {
            continue;
        }
        return result;
    }
    throw new IOException("Invalid varint");
}

