private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Check that the start and stop nodes are valid
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must be non-null");
    }

    // Check that the direction is valid
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 or -1");
    }

    // Initialize the circulator to the start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Loop until we reach the stop node or find a node that satisfies the predicate
    while (!circulator.equals(stop)) {
        Node current = circulator.next().getValue();
        if (predicate.test(current)) {
            return circulator;
        }
    }

    // If we reach this point, no node satisfying the predicate was found, so return the circulator to the stop node
    return circulator;
}

