    // Check if the bucket's key is the same as the data table's key
    if (!Arrays.equals(bucketKey, dataset.key)) {
        return false;
    }
    // Check if the bucket's value is the same as the data table's value
    if (!Arrays.equals(bucketValue, dataset.value)) {
        return false;
    }
    // Check if the bucket's size is the same as the data table's size
    if (bucket.size() != dataset.size()) {
        return false;
    }
    // Check if the data type of each bucket is the same as the data type of each data table
    for (int i = 0; i < bucket.size(); i++) {
        if (bucket[i].dataType != dataset[i].dataType) {
            return false;
        }
    }
    // Check if the key and value of each bucket is the same as the key and value of each data table
    for (int i = 0; i < bucket.size(); i++) {
        if (!bucket[i].key.equals(dataset[i].key)) {
            return false;
        }
        if (!bucket[i].value.equals(dataset[i].value)) {
            return false;
        }
    }
    // If all checks pass, return true
    return true;
}

