public static <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) throw new NullPointerException("arr cannot be null");
    if (from < 0 || from >= arr.length) throw new IndexOutOfBoundsException("from index is out of bounds");
    if (to < 0 || to >= arr.length) throw new IndexOutOfBoundsException("to index is out of bounds");
    if (from >= to) throw new IllegalArgumentException("from index must be smaller than to index");

    for (int i = 0; i < (to - from) / 2; i++) {
        swap(arr, from + i, arr.length - 1 - i);
    }
}

private static <V> void swap(V[] arr, int i, int j) {
    V tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
}

