private List<Pair<Integer, Integer>> computeSeparatorList(E edge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (Integer v : graph.getNeighborhood(edge.getVertices().get(0))) {
        for (Integer w : graph.getNeighborhood(edge.getVertices().get(1))) {
