private static Type resolveBound(TypeVariable<?> typeVariable, List<Type> bounds) {
    if (bounds.isEmpty()) {
        return Unknown.class;
    }

    List<Type> upperBounds = bounds.stream().filter(type -> type.getUpperBounds().length == 1).collect(Collectors.toList());
    if (upperBounds.size() == 1) {
        return upperBounds.get(0);
    }

    List<Type> lowerBounds = bounds.stream().filter(type -> type.getLowerBounds().length == 1).collect(Collectors.toList());
    if (lowerBounds.size() == 1) {
        return lowerBounds.get(0);
    }

    throw new IllegalStateException("Multiple bounds for type variable " + typeVariable.getName() + " could not be resolved");
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if all neighbors of each vertex in the subgraph are also in the subgraph
    for (V vertex : vertices) {
        Set<V> neighbors = graph.adjacentVertices(vertex);
        if (!neighbors.containsAll(vertices)) {
            return false;
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int lowerBound = 0;
        for (K otherKey : keys) {
            if (key.compareTo(otherKey) < 0) {
                lowerBound++;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new NullPointerException("Descriptor cannot be null");
    }

    if (descriptor.startsWith("[")) {
        int dim = 1;
        while (descriptor.charAt(dim) == '[') {
            ++dim;
        }
        if (descriptor.charAt(dim) == 'L') {
            boolean isPrimitive = false;
            for (String primitiveType : PRIMITIVE_TYPES) {
                if (descriptor.substring(dim + 1, descriptor.length() - 1).equals(primitiveType)) {
                    isPrimitive = true;
                    break;
                }
            }
            if (!isPrimitive) {
                throw new IllegalArgumentException("Descriptor is not a valid primitive type: " + descriptor);
            }
        } else {
            throw new IllegalArgumentException("Descriptor is not a valid descriptor string: " + descriptor);
        }
    } else if (!PRIMITIVE_TYPES.contains(descriptor)) {
        throw new IllegalArgumentException("Descriptor is not a valid primitive type: " + descriptor);
    }

    for (int i = 0; i < descriptor.length(); ++i) {
        if (descriptor.charAt(i) == '[') {
            ++i;
        } else if (descriptor.charAt(i) == 'L') {
            i = descriptor.length();
        } else {
            break;
        }
    }

    String primitiveType = descriptor.substring(0, descriptor.length() - 1);
    switch (primitiveType) {
        case "boolean":
            popBoolean();
            break;
        case "byte":
            popByte();
            break;
        case "char":
            popChar();
            break;
        case "double":
            popDouble();
            break;
        case "float":
            popFloat();
            break;
        case "int":
            popInt();
            break;
        case "long":
            popLong();

