private static <K extends Comparable<K>> List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    if (keys.size() > 0) {
        upperBounds.add(keys.get(0));
        for (int i = 1; i < keys.size(); i++) {
            if (keys.get(i).compareTo(upperBounds.get(upperBounds.size() - 1)) > 0) {
                upperBounds.add(keys.get(i));
            }
        }
    }
    return upperBounds;
}

public static String encodeTemplateNames(String s) {
    // Split the string into an array of strings based on the '{' and '}' characters
    String[] templateNames = s.split("[{}]");
    // Create a new string builder to store the encoded template names
    StringBuilder sb = new StringBuilder();
    // Loop through each template name and encode it by replacing '{' and '}' with their corresponding percentage encoded strings
    for (String templateName : templateNames) {
        sb.append(templateName.replace("{", "%7B")
                            .replace("}", "%7D"));
    }
    // Return the encoded string
    return sb.toString();
}

