static String[] toNoNullStringArray(Object[] array) {
    String[] result = new String[array.length];
    int i = 0;
    for (Object object : array) {
        if (object != null) {
            result[i++] = object.toString();
        }
    }
    if (i < result.length) {
        result = Arrays.copyOf(result, i);
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int extensionIndex = filename.lastIndexOf(".");
    int lastSeparatorIndex = indexOfLastSeparator(filename);

    if (extensionIndex > lastSeparatorIndex) {
        return extensionIndex;
    } else {
        return -1;
    }
}

public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastUnixSeparatorIndex = filename.lastIndexOf("/");
    int lastWindowsSeparatorIndex = filename.lastIndexOf("\\");

    if (lastUnixSeparatorIndex > lastWindowsSeparatorIndex) {
        return lastUnixSeparatorIndex;
    } else {
        return lastWindowsSeparatorIndex;
    }
}

