    }
  }
  return contentRange;
}

public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File cannot be null");
    }
    if (!file.exists()) {
        throw new FileNotFoundException("File not found");
    }
    if (!file.isFile()) {
        throw new IllegalArgumentException("File must be a regular file");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges cannot be null");
    }
    if (timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be empty");
    }

    // Check if the time ranges are sorted
    if (!isSortedByStartTimeWithNoOverlap(timeRanges)) {
        throw new IllegalArgumentException("Time ranges must be sorted by start time");
    }

    // Load the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot != null) {
                if (isTimeWithinRange(threadSnapshot.getTime(), timeRanges)) {
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
    }

    return threadSnapshots;
}
